  const set = React.useCallback((next) => {
    const tag = keyRef.current
    setCell((prev) => {
      const base = prev.key === tag ? prev.value : initial
      return { key: tag, value: typeof next === 'function' ? next(base) : next }
    })
  }, [initial])
  return [cell.key === key ? cell.value : initial, set]
