  if (!status) {
    return { state: 'unknown', lifecycle: [] }
  }
  const lifecycle = []
  if (status.pending) {
    lifecycle.push('pending')
  }
  if (status.active) {
    lifecycle.push('running')
  }
  const state = status.state ?? 'unknown'
  return { state, lifecycle }
